// Aus dem Rohtext alle Zeilen ziehen, die einem Itemnamen sehr ähnlich sind
function extractNames(raw){
  const segmente=segmentText(raw);
  const gefunden=[],used={};
  segmente.forEach(function(seg){
    // Alle Items sammeln, die zu diesem Segment passen - nicht nur den besten.
    const treffer=[];
    marketItems.forEach(function(item){
      const sc=scoreLine(seg,item);
      const shared=sharedTokenCount(seg,item);
      const minScore=(shared>=2)?68:85;
      if(sc>=minScore)treffer.push({item:item,score:sc});
    });
    treffer.sort(function(a,b){return b.score-a.score});
    // Hoechstens zwei Treffer pro Segment, damit nichts doppelt durchrutscht
    treffer.slice(0,2).forEach(function(t){
      if(!used[t.item.slug]){
        used[t.item.slug]=1;
        gefunden.push({name:t.item.name,score:t.score,line:seg});
      }
    });
  });
  gefunden.sort(function(a,b){return b.score-a.score});
  if(gefunden.length)return {names:gefunden.map(function(g){return g.name}),certain:true};
  return {names:[],certain:false};
}

// Zerlegt den OCR-Text in einzelne Kandidaten. Auf dem Belohnungsbildschirm
// kleben mehrere Namen aneinander, z.B. "Frost: Neuroptri Garuda: Neuroptik".
function segmentText(raw){
  const zeilen=raw.split(String.fromCharCode(10)).map(function(x){return cleanLine(x)})
    .filter(function(x){return x.length>3});
  const out=[];
  const muster=/[A-Z\u00c4\u00d6\u00dc][\w\u00e4\u00f6\u00fc\u00df-]*(?:\s+(?:Prime|Wraith|Vandal|Kuva|Tenet))?\s*[:.]?\s*(?:Blaupause|Chassis|Neuroptik|Systeme|Lauf|Verschluss|Kolben|Griff|Klinge|Sehne|Panzer|Gehirn|Set|Verbindung|Geschirr|Fl\u00fcgel|Schenkel|Verzierung|Kette|Handschuh|Stiefel|Band|Beutel|Schnalle|Sterne|Scheibe|Schutz|Kopf|Motor|Kern|Federn|Stoff|Kiefer)/g;
  zeilen.forEach(function(z){
    let m,treffer=[];
    while((m=muster.exec(z))!==null)treffer.push(m[0].trim());
    if(treffer.length){
      // Muster gefunden: genau diese Teilstuecke bewerten, den Rest der Zeile nicht
      treffer.forEach(function(t){out.push(t)});
      return;
    }
    // kein Muster: die ganze Zeile plus ihre direkten Wortpaare
    out.push(z);
    const w=z.split(' ').filter(function(x){return x.length>2});
    for(let i=0;i<w.length-1;i++)out.push(w[i]+' '+w[i+1]);
  });
  return out;
}

async function judgeRelics(){
  const raw=$('#relicInput').value.split(String.fromCharCode(10)).map(function(x){return x.trim()}).filter(Boolean);
  if(!raw.length){toast('Bitte zuerst fotografieren oder Namen eintragen');return}
  const box=$('#relicResult');
  const rows=[];
  for(let i=0;i<raw.length;i++){
    box.innerHTML='<div class="progress-note">Preise werden geprüft \\u2026 ('+(i+1)+'/'+raw.length+')</div>';
    const item=matchItem(raw[i]);
    if(!item){
      rows.push({name:raw[i],shown:'',slug:'',price:null,source:'unbekannt',error:'Nicht in der Itemliste'});
    }else{
      const p=await fetchTopPrice(item);
      rows.push({name:raw[i],shown:item.name,slug:item.slug,price:p.price,source:p.source,error:p.error});
    }
    await new Promise(function(r){setTimeout(r,340)});
  }
  const withPrice=rows.filter(function(r){return r.price});
  const sorted=withPrice.slice().sort(function(a,b){return b.price-a.price});
  const best=sorted.length?sorted[0]:null;
  renderVerdict(rows,best);
}

function renderVerdict(rows,best){
  const box=$('#relicResult');
  let html='';
  if(best){
    html+='<div class="verdict"><span>AM WERTVOLLSTEN</span><strong>'+best.name+'</strong><em>ca. '+best.price+' Platin</em></div>';
  }else{
    html+='<div class="verdict" style="background:linear-gradient(135deg,#ff9aa6,#c0455a)"><span>KEIN PREIS ERMITTELT</span><strong>Namen prüfen</strong><em>Bitte Schreibweise kontrollieren</em></div>';
  }
  const sorted=rows.slice().sort(function(a,b){return (b.price||0)-(a.price||0)});
  sorted.forEach(function(r){
    const i=rows.indexOf(r);
    const isBest=best&&r.name===best.name;
    const note=r.source==='live'?'Live-Angebot von Warframe.market':r.source==='schaetzung'?'Lokale Schätzung \\u2013 API nicht erreichbar':(r.error||'Kein Preis');
    html+='<article class="relic-card'+(isBest?' best':'')+'">'
      +'<div class="rank">'+(isBest?'\\u2605':i+1)+'</div>'
      +'<div><h4>'+r.name+'</h4><p>'+note+(r.shown&&r.shown!==r.name?' \\u00b7 erkannt als '+r.shown:'')+'</p></div>'
      +'<div class="relic-price"><strong>'+(r.price==null?'\\u2013':r.price)+'</strong><small>'+(r.price==null?'kein Preis':'Platin')+'</small></div>'
      +'<div class="relic-actions">'
      +'<button class="mini-action" data-addrow="'+i+'">+ Inventar</button>'
      +'<a class="mini-action gold" href="https://warframe.market/items/'+r.slug+'?type=sell" target="_blank" rel="noopener">Verkaufen \\u2197</a>'
      +'</div></article>';
  });
  box.innerHTML=html;
  $$('[data-addrow]').forEach(function(b){
    b.onclick=function(){
      const r=rows[Number(b.dataset.addrow)];
      addToSession(r.name,r.price);
      openResultFor(r.name,r.price);
    };
  });
}

function addToSession(name,price){
  if(!name||!name.trim())return;
  session.push({name:name.trim(),price:price||null});
  toast('Zum Inventar hinzugefügt');
}

// ===== V20: Sammelliste fuer ganze Missionen =====
let missionItems=[];  // {name, slug, price, source}

function addMissionItem(name,price,slug){
  if(!name||!name.trim())return false;
  const key=(slug||name).toLowerCase();
  const vorhanden=missionItems.find(function(x){return (x.slug||x.name).toLowerCase()===key});
  if(vorhanden){
    if(price&&(!vorhanden.price||price<vorhanden.price))vorhanden.price=price;
    return false;
  }
  missionItems.push({name:name.trim(),slug:slug||'',price:price||null,source:price?'live':'offen'});
  return true;
}

function renderMission(){
  const box=document.getElementById('missionList');
  if(!box)return;
  if(!missionItems.length){
    box.innerHTML='<div class="empty">Noch keine Gegenstaende gesammelt. Fotografiere Belohnungen oder trage sie in die vier Felder ein.</div>';
    return;
  }
  const sortiert=missionItems.slice().sort(function(a,b){return (b.price||0)-(a.price||0)});
  const summe=sortiert.reduce(function(a,x){return a+(x.price||0)},0);
  box.innerHTML='<div class="winner-banner">'+sortiert.length+' Gegenstaende · Gesamtwert ca. '+summe+' Platin</div>'
    +sortiert.map(function(x,i){
      return '<article class="relic-card'+(i===0&&x.price?' best':'')+'">'
        +'<div class="rank">'+(i===0&&x.price?'\u2605':i+1)+'</div>'
        +'<div><h4>'+x.name+'</h4><p>'+(x.price?'Wert ca. '+x.price+' Platin':'Preis noch offen')+'</p></div>'
        +'<div class="relic-price"><strong>'+(x.price==null?'\u2013':x.price)+'</strong><small>'+(x.price==null?'kein Preis':'Platin')+'</small></div>'
        +'<div class="relic-actions">'
        +'<button class="mini-action" data-mdel="'+i+'">Entfernen</button>'
        +(x.slug?'<a class="mini-action gold" href="https://warframe.market/items/'+x.slug+'?type=sell" target="_blank" rel="noopener">Verkaufen \u2197</a>':'')
        +'</div></article>';
    }).join('');
  document.querySelectorAll('[data-mdel]').forEach(function(b){
    b.onclick=function(){
      const x=sortiert[Number(b.dataset.mdel)];
      missionItems=missionItems.filter(function(y){return y!==x});
      renderMission();
    };
  });
}

async function valueMission(){
  renderMission();
  const offen=missionItems.filter(function(x){return !x.price});
  if(!offen.length){toast('Alle Preise liegen vor');return}
  const box=document.getElementById('missionList');
  for(let i=0;i<offen.length;i++){
    if(box)box.innerHTML='<div class="progress-note">Preise werden geholt \u2026 ('+(i+1)+'/'+offen.length+')</div>';
    const item=matchItemRaw(offen[i].name);
    if(item){
      const p=await fetchTopPrice(item);
      offen[i].slug=item.slug;
      offen[i].price=p.price;offen[i].source=p.source;
    }
    await new Promise(function(r){setTimeout(r,340)});
  }
  renderMission();
}

// Wie matchItem, aber ohne die harte Schwelle - fuer Namen, die schon geprueft sind
function matchItemRaw(name){
  const n=normalize(name);
  let hit=marketItems.find(function(x){return normalize(x.name)===n||normalize(x.nameDe||'')===n});
  if(hit)return hit;
  let best=null;
  marketItems.forEach(function(it){
    const sc=scoreLine(name,it);
    if(!best||sc>best.score)best={item:it,score:sc};
  });
  return (best&&best.score>=55)?best.item:null;
}

function openResultFor(name,price){
  current=matchItem(name);
  current.price=price||current.price||10;
  $('#resultName').textContent=current.name;
  $('#resultSlug').textContent=current.slug;
  $('#resultInitial').textContent=current.name[0].toUpperCase();
  $('#priceInput').value=current.price;
  $('#resultPrice').textContent=current.price;
  $('#quantityInput').value=1;
  $('#notesInput').value='';
  $('#marketLink').href='https://warframe.market/items/'+current.slug+'?type=sell';
  $('#overframeLink').href='https://overframe.gg/items/all/?q='+encodeURIComponent(current.base.replaceAll('-',' '));
  go('result');
}

async function handleRelicPhotos(files){
  const list=[].slice.call(files||[]);
  if(!list.length)return;
  go('relic');
  let allNames=[];
  for(let i=0;i<list.length;i++){
    const f=list[i];
    addPhoto(URL.createObjectURL(f));
    setRelicStatus('Foto '+(i+1)+' von '+list.length+' wird gelesen \\u2026');
    try{
      const raw=await readOnePhoto(f,'Foto '+(i+1));
      lastRawText=raw;
      const names=extractNames(raw);
      names.forEach(function(n){if(allNames.indexOf(n)<0)allNames.push(n)});
      const box=$('#relicInput');
      box.value=allNames.join(String.fromCharCode(10));
    }catch(e){
      setRelicStatus('Foto '+(i+1)+' konnte nicht gelesen werden: '+(e.message||e));
      console.error(e);
    }
  }
  if(!allNames.length){
    showRawText();
    setRelicStatus('Keine Belohnung sicher erkannt. Prüfe unten den gelesenen Text und tippe die Namen gegebenenfalls selbst ein.');
    return;
  }
  // Erkannte Namen sofort in die Sammelliste uebernehmen, damit keine Klicks noetig sind
  let uebernommen=0;
  allNames.forEach(function(n){
    const it=matchItemRaw(n);
    if(addMissionItem(it?it.name:n,null,it?it.slug:''))uebernommen++;
  });
  if(uebernommen){
    renderMission();
    setRelicStatus('Fertig. '+allNames.length+' erkannt, '+uebernommen+' neu in der Sammelliste.');
  }
  await judgeRelics();
}

